//! Independent native event grammar and byte splits; not generated by the codec.
use morphiecore::{
    adapter::UpstreamAdapter,
    execution::Attempt,
    protocol::{
        anthropic::{MessageSseDecoder, Profile},
        native::ReplayTarget,
        stream::{SseError, SseLimits},
    },
    semantic::task::generation::LocalScope,
};
use serde_json::{Value, json};
fn native_attempt(target: ReplayTarget) -> Attempt {
    Attempt::new(
        UpstreamAdapter::AnthropicMessages {
            profile: Profile::AdaptiveTextTools,
            target,
        },
        2 << 20,
        SseLimits::default(),
    )
}
fn frames() -> Vec<Value> {
    vec![
        json!({"type":"message_start","message":{"id":"msg","type":"message","role":"assistant","model":"synthetic-model",
            "content":[],"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":11,"output_tokens":0,
                "cache_creation_input_tokens":4,"cache_read_input_tokens":3}}}),
        json!({"type":"ping"}),
        json!({"type":"content_block_start","index":0,"content_block":{"type":"thinking","thinking":"","signature":""}}),
        json!({"type":"content_block_delta","index":0,"delta":{"type":"thinking_delta","thinking":"雪"}}),
        json!({"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":"sig-"}}),
        json!({"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":"tail"}}),
        json!({"type":"content_block_stop","index":0}),
        json!({"type":"content_block_start","index":1,"content_block":{"type":"text","text":""}}),
        json!({"type":"content_block_delta","index":1,"delta":{"type":"text_delta","text":"ok"}}),
        json!({"type":"content_block_stop","index":1}),
        json!({"type":"content_block_start","index":2,"content_block":{"type":"tool_use","id":"toolu_one","name":"lookup","input":{}}}),
        json!({"type":"content_block_delta","index":2,"delta":{"type":"input_json_delta","partial_json":"{\"z\":1.000000000000000001"}}),
        json!({"type":"content_block_delta","index":2,"delta":{"type":"input_json_delta","partial_json":",\"a\":\"v\"}"}}),
        json!({"type":"content_block_stop","index":2}),
        json!({"type":"message_delta","delta":{},"usage":{"output_tokens":7}}),
        json!({"type":"message_delta","delta":{"stop_reason":"tool_use","stop_sequence":null},"usage":{"output_tokens":9}}),
        json!({"type":"message_stop"}),
    ]
}
fn wire(frames: &[Value]) -> Vec<u8> {
    frames
        .iter()
        .map(|v| format!("event: {}\ndata: {v}\n\n", v["type"].as_str().unwrap()))
        .collect::<String>()
        .into_bytes()
}
fn feed(d: &mut MessageSseDecoder, mut bytes: &[u8]) -> Result<(), SseError> {
    while !bytes.is_empty() {
        let used = d.consume(bytes)?;
        assert!(used > 0);
        bytes = &bytes[used..];
    }
    Ok(())
}
fn expected() -> Value {
    serde_json::from_str(r#"{"id":"msg","type":"message","role":"assistant","model":"synthetic-model",
        "content":[{"type":"thinking","thinking":"雪","signature":"sig-tail"},{"type":"text","text":"ok"},
            {"type":"tool_use","id":"toolu_one","name":"lookup","input":{"z":1.000000000000000001,"a":"v"}}],
        "stop_reason":"tool_use","stop_sequence":null,"usage":{"input_tokens":11,"output_tokens":9,
            "cache_creation_input_tokens":4,"cache_read_input_tokens":3}}"#).unwrap()
}
#[test]
fn audit_nullable_usage_deltas_preserve_known_counts_but_zero_updates_them() {
    for read in [Value::Null, json!(0), json!(5)] {
        let mut values = frames();
        values[0]["message"]["usage"]["output_tokens"] = json!(2);
        values[0]["message"]["usage"]["output_tokens_details"] = json!({"thinking_tokens":2});
        values[15]["usage"] = json!({"output_tokens":9,"input_tokens":null,
            "cache_creation_input_tokens":null,"cache_read_input_tokens":read,
            "output_tokens_details":null});
        let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
        let mut attempt = native_attempt(target);
        attempt.begin(200, "text/event-stream").unwrap();
        for chunk in wire(&values).chunks(7) {
            let mut rest = chunk;
            while !rest.is_empty() {
                let (n, events) = attempt.push(rest).unwrap();
                assert!(!events.iter().any(|e| matches!(
                    e,
                    morphiecore::semantic::task::generation::StreamEvent::Terminal { .. }
                )));
                rest = &rest[n..];
            }
        }
        let usage = attempt.finish().unwrap().semantic.usage().unwrap();
        assert_eq!(
            (
                usage.input_tokens,
                usage.input_cache_write_tokens,
                usage.cached_input_tokens,
                usage.output_tokens,
                usage.reasoning_tokens
            ),
            (
                Some(11),
                Some(4),
                Some(read.as_u64().unwrap_or(3)),
                Some(9),
                Some(2)
            )
        );
    }
}
#[test]
fn malformed_unclosed_or_trailing_streams_never_recover_success() {
    let original = frames();
    let mut cases = Vec::new();
    for index in [0, 6, 9, 13, 16] {
        let mut v = original.clone();
        v.remove(index);
        cases.push(v);
    }
    let mut v = original.clone();
    v[11]["delta"]["partial_json"] = json!("{\"z\":1,\"z\":2");
    cases.push(v);
    let mut v = original.clone();
    v[11]["delta"]["partial_json"] = json!("{\"z\":1");
    v.remove(12);
    cases.push(v);
    let mut v = original.clone();
    v[12]["delta"]["type"] = json!("text_delta");
    cases.push(v);
    let mut v = original.clone();
    v[7]["index"] = json!(0);
    cases.push(v);
    let mut v = original.clone();
    v[4]["index"] = json!(1);
    cases.push(v);
    let mut v = original.clone();
    v.insert(6, original[3].clone());
    cases.push(v);
    let mut v = original.clone();
    v[2]["content_block"]["signature"] = json!("opening-signature");
    cases.push(v);
    let mut v = original.clone();
    v[10]["content_block"]["input"] = json!({"key":"not-an-opening-fragment"});
    cases.push(v);
    let mut v = original.clone();
    v.insert(7, original[6].clone());
    cases.push(v);
    for at in [1, 16, 17] {
        let mut v = original.clone();
        v.insert(
            at,
            json!({"type":"error","error":{"type":"overloaded_error","message":"synthetic"}}),
        );
        cases.push(v);
    }
    let mut v = original.clone();
    v.push(json!({"type":"ping"}));
    cases.push(v);
    for case in cases {
        let mut d = MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
        let failed = feed(&mut d, &wire(&case)).is_err();
        assert!(failed || d.finish().is_err());
        assert!(feed(&mut d, &wire(&original)).is_err());
    }
    let mut d = MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    let mut truncated = wire(&original);
    truncated.truncate(truncated.len() - 2);
    feed(&mut d, &truncated).unwrap();
    assert!(d.finish().is_err());
}
#[test]
fn limits_http_and_attempt_cancellation_are_independent_boundaries() {
    assert!(MessageSseDecoder::new(201, "text/event-stream", SseLimits::default()).is_err());
    assert!(
        MessageSseDecoder::new(
            200,
            "text/event-stream; charset=latin1",
            SseLimits::default()
        )
        .is_err()
    );
    let bytes = wire(&frames());
    for limits in [
        SseLimits {
            max_wire_bytes: bytes.len() - 1,
            ..SseLimits::default()
        },
        SseLimits {
            max_event_bytes: 64,
            ..SseLimits::default()
        },
        SseLimits {
            max_events: 2,
            ..SseLimits::default()
        },
    ] {
        let mut d = MessageSseDecoder::new(200, "text/event-stream", limits).unwrap();
        assert!(feed(&mut d, &bytes).is_err());
        assert!(d.finish().is_err());
    }
    let p = Profile::AdaptiveTextTools;
    let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
    let mut a = native_attempt(target.clone());
    a.begin(200, "text/event-stream").unwrap();
    let mut offset = 0;
    let mut incremental = vec![];
    while offset < bytes.len() {
        let (n, events) = a.push(&bytes[offset..]).unwrap();
        incremental.extend(events);
        offset += n;
    }
    assert!(matches!(
        incremental.first(),
        Some(morphiecore::semantic::task::generation::StreamEvent::Started)
    ));
    assert!(incremental.iter().any(|e| matches!(e, morphiecore::semantic::task::generation::StreamEvent::Delta {fragment,..} if fragment == "ok")));
    assert!(!incremental.iter().any(|e| matches!(
        e,
        morphiecore::semantic::task::generation::StreamEvent::Terminal { .. }
    )));
    assert!(a.response().is_err());
    let expected = p
        .decode_generation_response(
            &expected().to_string().into_bytes(),
            LocalScope::new(2),
            &target,
        )
        .unwrap();
    assert_eq!(a.finish().unwrap(), &expected);
    let mut a = native_attempt(target);
    a.begin(200, "text/event-stream").unwrap();
    a.push(&bytes[..100]).unwrap();
    a.cancel();
    assert!(a.push(&bytes).is_err());
    assert!(a.finish().is_err());
}
#[test]
fn unknown_upstream_fields_and_event_types_are_ignored() {
    let mut frames = frames();
    // Unknown extensions are distinct from modeled accounting details.
    frames[0]["message"]["usage"]["synthetic_future_usage"] = json!({"count":4});
    frames[0]["message"]["container"] = Value::Null;
    frames[2]["content_block"]["extra"] = json!({"nested":true});
    frames[15]["usage"]["synthetic_future_count"] = json!(0);
    frames[16]["future_field"] = json!(1);
    // Unknown event types carry no modeled content and are skipped.
    frames.insert(
        7,
        json!({"type":"synthetic_future_event","payload":{"anything":[1,2]}}),
    );
    let mut decoder =
        MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    feed(&mut decoder, &wire(&frames)).unwrap();
    let message = decoder.finish().unwrap();
    assert_eq!(
        Profile::AdaptiveTextTools
            .encode_response(&message)
            .unwrap(),
        expected()
    );
}
#[test]
fn scoped_accounting_preserves_opening_ttls_and_replaces_cumulative_tool_reports() {
    use morphiecore::{
        adapter::ClientAdapter,
        execution::ResponseDelivery,
        protocol::openai::stream::Obfuscation,
        semantic::task::generation::{StreamEvent, ToolUsageKind, UsageStage},
    };
    let mut values = frames();
    values[0]["message"]["usage"]["cache_creation"] =
        json!({"ephemeral_5m_input_tokens":1,"ephemeral_1h_input_tokens":3});
    values[0]["message"]["usage"]["server_tool_use"] =
        json!({"web_search_requests":0,"web_fetch_requests":2});
    values[14]["usage"]["server_tool_use"] =
        json!({"web_search_requests":1,"web_fetch_requests":3});
    values[14]["usage"]["output_tokens_details"] = json!({"thinking_tokens":2});
    values[15]["usage"]["server_tool_use"] = Value::Null;
    values[15]["usage"]["output_tokens_details"] = Value::Null;
    let mut attempt = native_attempt(ReplayTarget::new("provider", "synthetic-model").unwrap());
    attempt.begin(200, "text/event-stream").unwrap();
    let mut delivery = ResponseDelivery::new(
        ClientAdapter::Messages,
        "public",
        SseLimits::default(),
        Default::default(),
        Obfuscation::Disabled,
    );
    let mut output = vec![];
    let mut reports = vec![];
    for chunk in wire(&values).chunks(17) {
        let mut rest = chunk;
        while !rest.is_empty() {
            let (n, events) = attempt.push(rest).unwrap();
            rest = &rest[n..];
            reports.extend(events.iter().filter_map(|event| match event {
                StreamEvent::UsageReport(report) => Some(report.clone()),
                _ => None,
            }));
            let produced = delivery.encode_events(&attempt, &events).unwrap();
            if !produced.is_empty() && delivery.lifecycle().may_retry_or_fallback() {
                delivery.commit().unwrap();
            }
            output.extend(produced.into_iter().flatten());
        }
    }
    assert!(!String::from_utf8_lossy(&output).contains("message_stop"));
    attempt.finish().unwrap();
    output.extend(
        delivery
            .finish_stream(&attempt)
            .unwrap()
            .into_iter()
            .flatten(),
    );
    delivery.complete(&attempt).unwrap();
    assert_eq!(
        reports.iter().map(|r| r.stage).collect::<Vec<_>>(),
        [
            UsageStage::Checkpoint,
            UsageStage::Checkpoint,
            UsageStage::Checkpoint,
            UsageStage::Final
        ]
    );
    assert_eq!(
        reports
            .iter()
            .map(|r| r.counts.output_tokens)
            .collect::<Vec<_>>(),
        [Some(0), Some(7), Some(9), Some(9)]
    );
    let source = attempt.response().unwrap();
    let report = source.semantic.usage_reports().operation().unwrap();
    assert_eq!(report.counts.reasoning_tokens, Some(2));
    assert_eq!(
        report
            .details
            .tool_requests
            .iter()
            .find(|r| r.kind == ToolUsageKind::WebSearch)
            .unwrap()
            .count,
        Some(1)
    );
    let frames: Vec<Value> = std::str::from_utf8(&output)
        .unwrap()
        .lines()
        .filter_map(|line| line.strip_prefix("data: "))
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    assert_eq!(
        frames[0]["message"]["usage"]["cache_creation"],
        json!({"ephemeral_5m_input_tokens":1,"ephemeral_1h_input_tokens":3})
    );
    let final_usage = &frames
        .iter()
        .find(|f| f["type"] == "message_delta")
        .unwrap()["usage"];
    assert!(final_usage.get("cache_creation").is_none());
    assert_eq!(
        final_usage["server_tool_use"],
        json!({"web_search_requests":1,"web_fetch_requests":3})
    );
    let mut decoder =
        MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    feed(&mut decoder, &output).unwrap();
    let native = Profile::AdaptiveTextTools
        .encode_response(&decoder.finish().unwrap())
        .unwrap();
    let mut expected_usage = json!({"input_tokens":11,"output_tokens":9,
        "cache_read_input_tokens":3,"cache_creation_input_tokens":4,
        "cache_creation":{"ephemeral_5m_input_tokens":1,"ephemeral_1h_input_tokens":3},
        "server_tool_use":{"web_search_requests":1,"web_fetch_requests":3},
        "output_tokens_details":{"thinking_tokens":2}});
    assert_eq!(native["usage"], expected_usage);
    let (_, static_wire) = ClientAdapter::Messages.snapshot(source.clone()).unwrap();
    assert_eq!(static_wire["usage"], expected_usage);

    // An updated parent cannot make the opening TTL report silently change its meaning.
    values[15]["usage"]["cache_creation_input_tokens"] = json!(5);
    let mut contradictory =
        MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    assert!(feed(&mut contradictory, &wire(&values)).is_err());
    assert!(contradictory.finish().is_err());
    // Explicit zero replaces a nested report; null above did not erase it.
    values[15]["usage"]["cache_creation_input_tokens"] = json!(4);
    values[15]["usage"]["server_tool_use"] =
        json!({"web_search_requests":0,"web_fetch_requests":0});
    let mut zero = MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    feed(&mut zero, &wire(&values)).unwrap();
    expected_usage["server_tool_use"] = json!({"web_search_requests":0,"web_fetch_requests":0});
    assert_eq!(
        Profile::AdaptiveTextTools
            .encode_response(&zero.finish().unwrap())
            .unwrap()["usage"],
        expected_usage
    );
}
#[test]
fn known_upstream_fields_stay_strict() {
    for edit in [
        |f: &mut Vec<Value>| f[15]["usage"]["output_tokens"] = json!("9"),
        |f: &mut Vec<Value>| f[0]["message"]["usage"]["service_tier"] = json!("auto"),
        |f: &mut Vec<Value>| f[15]["usage"]["service_tier"] = json!("standard"),
        |f: &mut Vec<Value>| f[15]["delta"]["stop_reason"] = json!(7),
        |f: &mut Vec<Value>| f[3]["delta"]["type"] = json!("citations_delta"),
        |f: &mut Vec<Value>| f[2]["content_block"]["type"] = json!("redacted_thinking"),
    ] {
        let mut frames = frames();
        edit(&mut frames);
        let mut decoder =
            MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
        assert!(feed(&mut decoder, &wire(&frames)).is_err());
    }
}

#[test]
fn incremental_native_events_reduce_to_the_independent_static_semantics() {
    use morphiecore::protocol::anthropic::GenerationSseDecoder;
    use morphiecore::semantic::task::generation::{StreamState, materialize, reduce};
    let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
    for variant in 0..4 {
        let mut native = frames();
        let mut final_wire = expected();
        match variant {
            0 => {
                native[0]["message"]["usage"]["service_tier"] = json!("priority");
                final_wire["usage"]["service_tier"] = json!("priority");
            }
            1 => {
                native[3]["delta"]["thinking"] = json!("");
                final_wire["content"][0]["thinking"] = json!("");
            }
            2 => {
                native.remove(12);
                native.remove(11);
                final_wire["content"][2]["input"] = json!({});
                // Incomplete streams do not report a disposition; no Unreported
                // progress event may be emitted into the shared grammar.
                native[13]["delta"]["stop_reason"] = json!("max_tokens");
                final_wire["stop_reason"] = json!("max_tokens");
            }
            3 => {
                native[7]["content_block"]["text"] = json!("start ");
                final_wire["content"][1]["text"] = json!("start ok");
            }
            _ => {}
        }
        let expected = Profile::AdaptiveTextTools
            .decode_generation_response(
                final_wire.to_string().as_bytes(),
                LocalScope::new(2),
                &target,
            )
            .unwrap();
        for chunk_size in [1, 13, 4096] {
            let mut decoder = GenerationSseDecoder::new(
                200,
                "text/event-stream",
                SseLimits::default(),
                LocalScope::new(2),
                target.clone(),
            )
            .unwrap();
            let mut state = StreamState::new();
            for chunk in wire(&native).chunks(chunk_size) {
                let mut rest = chunk;
                while !rest.is_empty() {
                    let (used, events) = decoder.consume(rest).unwrap();
                    assert!(used > 0);
                    rest = &rest[used..];
                    for event in events {
                        state = reduce(state, event).unwrap();
                    }
                }
            }
            decoder.finish().unwrap();
            assert_eq!(materialize(&state).unwrap(), expected.semantic);
            assert_eq!(decoder.metadata().unwrap(), &expected.metadata);
        }
    }
}

#[test]
fn native_events_deliver_both_clients_and_keep_terminal_behind_eof() {
    use morphiecore::{
        execution::ResponseDelivery,
        protocol::{
            openai::{Adapter, Dialect, Profile as ClientProfile, TargetCaps, stream::Obfuscation},
            replay_envelope,
        },
        semantic::task::generation::{Item, Outcome, ToolArguments},
    };
    for profile in [ClientProfile::Responses, ClientProfile::Chat] {
        for incomplete in [false, true] {
            let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
            let mut attempt = native_attempt(target);
            let client = Adapter::new(profile, Dialect::MorphieCore, None);
            let mut delivery = ResponseDelivery::new(
                morphiecore::adapter::ClientAdapter::openai(client.clone(), TargetCaps::full()),
                "public",
                SseLimits::default(),
                morphiecore::semantic::context::StreamOptions {
                    include_usage: morphiecore::semantic::value::Presence::Value(true),
                    include_obfuscation: morphiecore::semantic::value::Presence::Value(false),
                },
                Obfuscation::Disabled,
            );
            attempt.begin(200, "text/event-stream").unwrap();
            let mut native = frames();
            native[15]["usage"]["output_tokens_details"] = json!({"thinking_tokens":2});
            if incomplete {
                native[15]["delta"]["stop_reason"] = json!("max_tokens");
            }
            let mut output = vec![];
            for (n, frame) in native.iter().enumerate() {
                let bytes = wire(std::slice::from_ref(frame));
                let mut rest = bytes.as_slice();
                while !rest.is_empty() {
                    let (used, events) = attempt.push(rest).unwrap();
                    rest = &rest[used..];
                    let produced = delivery.encode_events(&attempt, &events).unwrap();
                    if !produced.is_empty() && delivery.lifecycle().may_retry_or_fallback() {
                        delivery.commit().unwrap();
                    }
                    output.extend(produced.into_iter().flatten());
                }
                if n == 8 {
                    assert!(String::from_utf8_lossy(&output).contains("ok"));
                    assert!(attempt.response().is_err());
                    assert!(!delivery.lifecycle().may_retry_or_fallback());
                }
            }
            let early = String::from_utf8_lossy(&output);
            assert!(
                !early.contains("response.completed")
                    && !early.contains("response.incomplete")
                    && !early.contains("[DONE]")
            );
            attempt.finish().unwrap();
            output.extend(
                delivery
                    .finish_stream(&attempt)
                    .unwrap()
                    .into_iter()
                    .flatten(),
            );
            delivery.complete(&attempt).unwrap();
            let wire = String::from_utf8(output).unwrap();
            assert!(!wire.contains("sig-tail"));
            let mut decoder = client.event_decoder();
            let mut times = std::collections::BTreeSet::new();
            for data in wire.lines().filter_map(|line| line.strip_prefix("data: ")) {
                if data == "[DONE]" {
                    decoder.done().unwrap();
                    continue;
                }
                let value: Value = serde_json::from_str(data).unwrap();
                if let Some(t) = value
                    .get("created")
                    .or_else(|| value.pointer("/response/created_at"))
                {
                    times.insert(t.to_string());
                }
                decoder.push(&value).unwrap();
            }
            decoder.finish().unwrap();
            let decoded = decoder.materialize().unwrap();
            assert_eq!(times.len(), 1);
            assert_eq!(
                decoded.semantic.outcome(),
                if incomplete {
                    Outcome::Incomplete
                } else {
                    Outcome::Completed
                }
            );
            assert_eq!(decoded.semantic.usage().unwrap().total_tokens, Some(27));
            assert_eq!(decoded.semantic.usage().unwrap().reasoning_tokens, Some(2));
            let Item::Reasoning(reasoning) = &decoded.semantic.items()[0].1 else {
                panic!("reasoning");
            };
            let (issuer, format, token) =
                replay_envelope::open(reasoning.replay.as_ref().unwrap().as_str()).unwrap();
            assert_eq!(
                issuer,
                replay_envelope::issuer("synthetic-provider", "synthetic-model")
            );
            assert_eq!(
                format,
                morphiecore::semantic::task::generation::ReplayFormat::AnthropicMessagesThinking
            );
            assert_eq!(token.as_str(), "sig-tail");
            let call = decoded
                .semantic
                .items()
                .iter()
                .find_map(|(_, item)| match item {
                    Item::ToolCall(call) => Some(call),
                    _ => None,
                })
                .unwrap();
            let ToolArguments::Raw(arguments) = &call.arguments else {
                panic!("raw target arguments");
            };
            assert_eq!(
                serde_json::from_str::<Value>(arguments).unwrap(),
                expected()["content"][2]["input"]
            );
            // The same native SSE intake can also supply a non-streaming client.
            let native = attempt.response().unwrap().clone();
            let mut json_delivery = ResponseDelivery::new(
                morphiecore::adapter::ClientAdapter::openai(client.clone(), TargetCaps::full()),
                "public",
                SseLimits::default(),
                Default::default(),
                Obfuscation::Disabled,
            );
            let body: Value =
                serde_json::from_slice(&json_delivery.encode_json(&attempt).unwrap()).unwrap();
            assert_eq!(body["usage"]["total_tokens"], 27);
            let output_details = if profile == ClientProfile::Responses {
                "output_tokens_details"
            } else {
                "completion_tokens_details"
            };
            assert_eq!(body["usage"][output_details]["reasoning_tokens"], 2);
            let args = if profile == ClientProfile::Responses {
                &body["output"][2]["arguments"]
            } else {
                &body["choices"][0]["message"]["tool_calls"][0]["function"]["arguments"]
            };
            assert_eq!(
                serde_json::from_str::<Value>(args.as_str().unwrap()).unwrap(),
                expected()["content"][2]["input"]
            );
            assert_eq!(attempt.response().unwrap(), &native);
        }
    }
    let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
    let mut attempt = native_attempt(target);
    attempt.begin(200, "text/event-stream").unwrap();
    let mut native = frames();
    native[0]["message"]["usage"]["service_tier"] = json!("priority");
    let mut delivery = ResponseDelivery::new(
        morphiecore::adapter::ClientAdapter::Messages,
        "public",
        SseLimits::default(),
        Default::default(),
        Obfuscation::Disabled,
    );
    let mut output = vec![];
    let bytes = wire(&native);
    let mut rest = bytes.as_slice();
    while !rest.is_empty() {
        let (used, events) = attempt.push(rest).unwrap();
        rest = &rest[used..];
        let produced = delivery.encode_events(&attempt, &events).unwrap();
        if !produced.is_empty() && delivery.lifecycle().may_retry_or_fallback() {
            delivery.commit().unwrap();
        }
        output.extend(produced.into_iter().flatten());
    }
    assert!(!String::from_utf8_lossy(&output).contains("event: message_stop"));
    attempt.finish().unwrap();
    output.extend(
        delivery
            .finish_stream(&attempt)
            .unwrap()
            .into_iter()
            .flatten(),
    );
    delivery.complete(&attempt).unwrap();
    let mut decoded =
        MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    feed(&mut decoded, &output).unwrap();
    assert_eq!(
        decoded.finish().unwrap().usage.service_class,
        morphiecore::semantic::value::Presence::Value(
            morphiecore::semantic::context::ServiceClass::PriorityCapacity
        )
    );
}

#[test]
fn input_transformations_are_validated_then_omitted_with_a_receipt() {
    use morphiecore::protocol::{anthropic::GenerationSseDecoder, fidelity::Normalization};
    let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
    let omitted = Normalization::Omitted {
        rule: "messages.omit-input-transformations.v1",
        field: "response.input_transformations",
    };
    let entries = json!([{"type":"thinking_dropped","path":"messages.1.content.0"}]);
    let stream = |frames: &[Value]| {
        let mut decoder = GenerationSseDecoder::new(
            200,
            "text/event-stream",
            SseLimits::default(),
            LocalScope::new(2),
            target.clone(),
        )
        .unwrap();
        let bytes = wire(frames);
        let mut rest = &bytes[..];
        while !rest.is_empty() {
            let (used, _) = decoder.consume(rest).unwrap();
            rest = &rest[used..];
        }
        decoder.finish().unwrap();
        decoder.fidelity().normalizations().contains(&omitted)
    };
    assert!(!stream(&frames()));
    let mut native = frames();
    native[15]["input_transformations"] = entries.clone();
    assert!(stream(&native));
    let decode = |message: &Value| {
        Profile::AdaptiveTextTools.decode_generation_response(
            message.to_string().as_bytes(),
            LocalScope::new(2),
            &target,
        )
    };
    assert!(
        !decode(&expected())
            .unwrap()
            .fidelity
            .normalizations()
            .contains(&omitted)
    );
    // Unknown entry types are ignored, as documented; known ones stay strict.
    for (list, receipt) in [
        (entries, true),
        (json!([{"type":"future_report"}]), true),
        (json!([]), false),
        (Value::Null, false),
    ] {
        let mut message = expected();
        message["input_transformations"] = list;
        let decoded = decode(&message).unwrap();
        assert_eq!(
            decoded.fidelity.normalizations().contains(&omitted),
            receipt
        );
    }
    for list in [
        json!([{"type":"thinking_dropped"}]),
        json!([{"path":"messages.1"}]),
        json!({"type":"thinking_dropped"}),
    ] {
        let mut message = expected();
        message["input_transformations"] = list;
        assert!(decode(&message).is_err());
    }
}
